// === Tab: mySketch ===
//  Creative Coding homework Week 8, create a particle system.
//
// click mouse to add more seeds

//CLASS DEFINITION
class DandelionSeed {

	//OBJECT CONSTRUCTOR FUNCTION
	constructor(posX, posY, sSize) {
		this.posX = posX;
		this.posY = posY;
		this.col = color(204); //silver grey for seeds
	  this.size = sSize;
		this.speed = 0.05;
		this.lifespan = 100; //to control fade out of seeds
	}

	Breeze() {
		this.posX += this.speed;
		this.posY -= this.speed;
	}

	Fade() {
		this.lifespan -= 0.8;
		this.col = color(204, this.lifespan);
		this.size += 0.2;
	}
} //close class

var clock = []; //this will hold the floating seeds
var head = []; //holds the seeds that make up the dandelion head

function setup() {
	//frameRate(15);
	createCanvas(windowWidth, windowHeight);
	for (i = 1; i <= 50; i++) {
		clock.push(new DandelionSeed(random(i), random(-i, i),1));
	}
	for (i = 1; i <= 7; i++) {
		head.push(new DandelionSeed(0, 0,1));
	}
	for (i = 1; i <= 20; i++) {
		head.push(new DandelionSeed(0, -10,1));
	}
	for (i = 1; i <= 40; i++) {
		head.push(new DandelionSeed(0, -20,1));
	}
	for (i = 1; i <= 83; i++) {
		head.push(new DandelionSeed(0, -30,1));
	}
} //end setup

function draw() {
	translate(width * 0.25, height * 0.60);
	background(4, 82, 184);
	text("Click to blow away the dandelion seeds.",100,100);
	strokeWeight(5); //draw stalk
	stroke(101, 140, 42);
	line(0, 0, 0, height);
	stroke(204);
	//draw stationary dandelion head, centre ring one
	for (var i = 0; i <= 7; i++) {
		push();
		rotate(TWO_PI * i / 7);
		drawSeed(head[i].posX, head[i].posY, 4);
		pop();
	}
	//second ring
	for (i = 8; i <= 28; i++) {
		push();
		rotate(TWO_PI * i / 20);
		drawSeed(head[i].posX, head[i].posY, 4);
		pop();
	}
	// third ring
	for (i = 29; i <= 69; i++) {
		push();
		rotate(TWO_PI * i / 40);
		drawSeed(head[i].posX, head[i].posY, 4);
		pop();
	}
	//fourth ring
	for (i = 70; i < head.length; i++) {
		push();
		rotate(TWO_PI * i / 60);
		drawSeed(head[i].posX, head[i].posY, 4);
		pop();
	}

	//draw stalk
	strokeWeight(5);
	stroke(101, 140, 42);
	line(0, 0, 0, height);

	//draw free floating seeds, seeds are removed when they have faded or reached the edge.
	for (i = 0; i < clock.length; i++) {
		stroke(clock[i].col);
		clock[i].Breeze();
		clock[i].Fade();
		drawSeed(clock[i].posX + clock[i].speed, clock[i].posY + clock[i].speed, clock[i].size);
		if (clock[i].lifespan <= 10 || clock[i].posX >=width || clock[i].posX <= -width  || clock[i].posY <= -height || clock[i].posY >= height) {
			clock.splice(i, 1);
		}
		print("new clock.length  ", clock.length);
	}
} //close draw()

//function to draw the shape of individual seeds
function drawSeed(x, y, size) {
	strokeWeight(2);
	beginShape(LINES);
	vertex(x * size / 2, y * size / 2); //centre line
	vertex(x * size / 2, (y - 12) * size / 2);
	vertex(x * size / 2, (y - 6) * size / 2); //left side
	vertex((x - 5) * size / 2, (y - 8) * size / 2);
	vertex(x * size / 2, (y - 6) * size / 2); // right side
	vertex((x + 5) * size / 2, (y - 8) * size / 2);
	endShape();
}

//add more floating seeds each time the mouse is clicked
function mousePressed() {
	for (i = 1; i <= 100; i++) {
		clock.push(new DandelionSeed(random(-i,i), random(-i, i),1));
	}
}

